{"results":[{"id":"R1","verdict":"not_addressed","reason":"onRefund only swaps JSON.parse for parseRefundEvent; no HMAC signature check or 401 branch before payouts.refund, and no signature/secret is read.","quotes":[],"missing":"HMAC verification of the raw body against the shared secret using a timing-safe compare, returning 401 before payouts.refund.","suggestion":{"summary":"Verify HMAC of raw body before refunding; reject with 401","code":"export async function onRefund(req: Request, res: Response): Promise<void> {
  const raw = await readRawBody(req);
  const sig = req.header('x-refund-signature') ?? '';
  const expected = crypto
    .createHmac('sha256', process.env.REFUND_WEBHOOK_SECRET!)
    .update(raw)
    .digest('hex');
  const sigBuf = Buffer.from(sig, 'utf8');
  const expBuf = Buffer.from(expected, 'utf8');
  if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
    res.status(401).end();
    return;
  }
  const event = parseRefundEvent(raw);
  await payouts.refund(event.orderId, event.amount);
}"}}]}
